import React from "react";
import Sidebar from "./components/Sidebar";

function App() {
  return (
    <div style={{
      display: "flex",
      background: "#0f172a",
      color: "white",
      minHeight: "100vh"
    }}>
      <Sidebar />
      <h1 style={{ padding: "30px" }}>Testing</h1>
    </div>
  );
}

export default App;
